mapper.update:
UPDATE CHAT_POST
SET title = #{title}
WHERE chat_post_idx = #{chatPostIdx}
AND user_idx = #{userIdx}

mapper.delete:
DELETE c
FROM CHAT_COMMENT c
INNER JOIN CHAT_POST p
ON c.chat_post_idx = p.chat_post_idx
WHERE c.chat_post_idx = #{chatPostIdx}
AND p.user_idx = #{userIdx}

DELETE FROM CHAT_POST
WHERE chat_post_idx = #{chatPostIdx}
AND user_idx = #{userIdx}

mapper.select:
SELECT COALESCE(MAX(comment_order), 0)
FROM CHAT_COMMENT
WHERE chat_post_idx = #{chatPostIdx}
